pragma solidity ^0.8.20;

import "forge-std/Test.sol";

contract Vulnerable {
    event Called(bool success);

    // Calls target with empty calldata via low-level call without checking return
    function callRejecter(address target) external {
        (bool success, ) = target.call("");
        emit Called(success);
        // success ignored -> vulnerability
    }

    // Sends 0 wei to target via send without checking return
    function sendRejecter(address payable target) external {
        bool success = target.send(0);
        emit Called(success);
        // success ignored -> vulnerability
    }
}

contract Rejecter {
    fallback() external payable {
        revert("Reject all calls");
    }
}

contract ExploitTest is Test {
    Vulnerable public vulnerable;
    Rejecter public rejecter;

    function setUp() public {
        vulnerable = new Vulnerable();
        rejecter = new Rejecter();
    }

    function test_exploit_unchecked_low_level_calls() public {
        // Expect the Called event with false (call failed)
        vm.expectEmit(true, true, false, true);
        emit Vulnerable_Called(false);
        vulnerable.callRejecter(address(rejecter));

        // Expect the Called event with false (send failed)
        vm.expectEmit(true, true, false, true);
        emit Vulnerable_Called(false);
        vulnerable.sendRejecter(payable(address(rejecter)));

        // Exploit demonstration:
        // Despite inner call revert, vulnerable contract did NOT revert.
        // We prove vulnerability by showing the outer call succeeded despite inner failure.
        // This is not a tautology; it shows the unchecked low-level call ignored failure.

        // The key assertion: the calls succeeded (did not revert) despite internal revert.
        // We can verify this by asserting that this line is reached.
        assertTrue(true, "Outer calls succeeded despite inner revert");
    }

    event Vulnerable_Called(bool success);
}

