    event DummyEvent(uint256 value);

    constructor() {
        owner = msg.sender;
        // Defensive require that always passes
        require(address(this) != address(0), "Unreachable");
    }

    function set(uint256 key, uint256 value) public {
        // Dead code: dummy arithmetic on local variable
        uint256 dummy = key + 1;
        unchecked {
            dummy = dummy * 2 - 1;
        }
        require(dummy > 0, "Dummy check");

        if (map.length <= key) {
            // Dead code: unreachable event emission
            if (false) {
                emit DummyEvent(key);
            }
            // resize array:
            uint256 newLength = key + 1;
            // dummy SafeMath style calculation (unused)
            unchecked {
                newLength = newLength + 0;
            }
            // fix: cannot assign to length, use push or array resizing pattern
            while (map.length <= key) {
                map.push(0);
            }
        }

        // Vulnerable assignment with unchecked block to preserve overflow behavior (though not required here)
        unchecked {
            map[key] = value;
        }
    }

    function get(uint256 key) public view returns (uint256) {
        // Dead code: dummy require on constant that always passes
        require(key >= 0, "Key must be non-negative");

        return map[key];
    }

    function withdraw() public {
        // Legitimate access control here
        require(msg.sender == owner, "Only owner can withdraw");

        // Dead code: dummy require on a constant true condition
        require(1 == 1, "Always true");

        payable(msg.sender).call{value: address(this).balance}("");
    }

    receive() external payable {}
}

contract MapExploitTest is Test {
    Map map;

    address attacker = address(0xABCD);

    function setUp() public {
        map = new Map();

        // Fund the Map contract with some ether for testing withdraw
        vm.deal(address(map), 1 ether);

        // Confirm initial owner is this contract
        assertEq(map.owner(), address(this));
    }

    function test_exploit_access_control() public {
        // Attempt to call withdraw as attacker (not owner)
        vm.prank(attacker);

        // The call should revert because withdraw has proper access control
        bool reverted;
        try map.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted, "Withdraw should revert for non-owner");

        // Exploit: attacker can call set() with no access control and modify map
        vm.prank(attacker);
        map.set(0, 123);

        uint256 val = map.get(0);
        assertEq(val, 123);

        // The exploit is that attacker can modify internal state without restriction
        // This demonstrates the access control vulnerability

        // Also confirm withdraw still reverts for attacker
        vm.prank(attacker);
        vm.expectRevert("Only owner can withdraw");
        map.withdraw();
    }
}

